fn double(value: i32) -> i32 { value * 2 }
#[cfg(test)]
mod tests {
    use super::double;
    #[test]
    fn doubles_positive() { assert_eq!(double(6), 12); }
}
fn main() { println!("{}", double(6)); }

fn eligible(value: i32) -> bool { value > 0 }
#[cfg(test)]
mod tests {
    use super::eligible;
    #[test]
    fn excludes_zero_and_negative() {
        assert!(eligible(1));
        assert!(!eligible(0));
        assert!(!eligible(-1));
    }
}
fn main() { println!("{}", eligible(0)); }

#[derive(Debug, PartialEq)]
struct Count(i32);
fn main() {
    let before = Count(3);
    let after = Count(4);
    assert_eq!(after, Count(4));
    assert_ne!(before, after);
    println!("{:?}", after);
}

